#nullable enable
namespace Grove.Media.Files;

/// <summary>
/// Files a module generates server-side (docs/media.md § 2, ruling 2026-10-05): written as new
/// file objects or versions through the file-object API, with the caller's access, so they are
/// scanned like uploads. Not every write: whether one is scanned depends on the module writing
/// it and the document type, and a module can be exempted for some or all types
/// (<see cref="MediaScanExemptionOptions"/>), as cooperative real-time editing needs. An exempt
/// write is recorded clean with the reason "exempt: generated by {module}", never handed to the
/// scanners: scanned or exempt, never both.
/// </summary>
public interface IMediaGeneratedFiles
{
    /// <param name="module">The module writing it (its feature or module id), as exemptions name it.</param>
    Task<MediaItem> CreateAsync(string module, MediaUpload upload, CancellationToken cancellationToken = default);

    /// <param name="publishWhenClean">The new version becomes the published one as soon as it is clean.</param>
    Task<MediaItem> WriteVersionAsync(string module, string placementId, Stream content, string? claimedType, bool publishWhenClean = true, CancellationToken cancellationToken = default);

    /// <summary>Whether a write by <paramref name="module"/> of this type and name skips scanning.</summary>
    bool IsExempt(string module, string? claimedType, string name);
}

/// <summary>
/// The modules whose generated files skip scanning, for which types. Modules add their own with
/// <c>services.Configure&lt;MediaScanExemptionOptions&gt;(options =&gt; options.Exempt(...))</c>;
/// the host adds more under <c>Grove_Media:Generated:Exemptions</c>
/// (<c>[{ "Module": "...", "Types": ["text/*", ".md"] }]</c>). Nothing is exempt by default.
/// </summary>
public sealed class MediaScanExemptionOptions
{
    public List<MediaScanExemption> Exemptions { get; set; } = [];

    /// <param name="types">MIME types (<c>text/markdown</c>), families (<c>text/*</c>), extensions
    /// (<c>.md</c>), or <c>*</c> for every type.</param>
    public MediaScanExemptionOptions Exempt(string module, params string[] types)
    {
        Exemptions.Add(new MediaScanExemption { Module = module, Types = [.. types] });
        return this;
    }

    public bool IsExempt(string module, string? claimedType, string name)
    {
        var extension = Path.GetExtension(name);
        return Exemptions.Any(exemption =>
            string.Equals(exemption.Module, module, StringComparison.OrdinalIgnoreCase) &&
            exemption.Types.Any(type =>
                type == "*" ||
                (type.StartsWith('.') && string.Equals(type, extension, StringComparison.OrdinalIgnoreCase)) ||
                (type.EndsWith("/*", StringComparison.Ordinal) && claimedType?.StartsWith(type[..^1], StringComparison.OrdinalIgnoreCase) == true) ||
                string.Equals(type, claimedType, StringComparison.OrdinalIgnoreCase)));
    }
}

public sealed class MediaScanExemption
{
    public string Module { get; set; } = string.Empty;

    public List<string> Types { get; set; } = [];
}
